"""Відомість і вартість BOS по етапах для рекомендованого рішення + втрати + порівняння з прикидкою 04.11 (calc.py).
Ціни — Б 26.10 (Китай FOB; Україна — ціни ринку), трудовитрати — люд.год на одиницю з кошторису Б 26.10."""
import json, math, collections
F = json.load(open('final.json')); B = json.load(open('boxes.json')); D = json.load(open('data.json'))
rows = F['rows']; T = {int(k): v for k, v in F['T'].items()}; TAU = B['TAU']
KIMP = 1.2; RATE = 15.59                       # FOB → на об'єкті; $/люд.год (700 грн)
TRAYP = {'100×50': 3.66, '200×50': 5.52, '300×100': 9.99, '400×100': 13.40, '600×100': 18.73}; TRAY_FIT = 1.53; TRAY_H = 0.1166 * 1.79
ALP = {120: 2.04, 185: 3.12, 240: 4.07}; LUGP = {120: 1.54, 185: 2.04, 240: 2.54}
items = {1: [], 2: []}
def it(st, grp, name, unit, q, p, src='cn', h=0.0, note=''):
    cost = q * p * (KIMP if src == 'cn' else 1.0); items[st].append(dict(grp=grp, name=name, unit=unit, q=q, p=p, src=src, cost=cost, h=q * h, note=note))
