nl = {st: [r for r in rows if r['st'] == st] for st in (1, 2)}
# 06.11: кількості фасадів — з розкладки (data.json → fac): схід лише козирок, вертикально — південь (calc/fac_bez_skhodu_vert.py)
FV, FC = D['fac']['vert'], D['fac']['can']; NV, NC = len(FV), len(FC)
def fac_groups(V, gap=0.25):                 # групи рейок фасаду: модулі, що торкаються (≤ 0,25 м), — одна група для вирівнювання і БЗ
    par = list(range(len(V)))
    def fd(i):
        while par[i] != i: par[i] = par[par[i]]; i = par[i]
        return i
    for i, a in enumerate(V):
        for j in range(i + 1, len(V)):
            b = V[j]
            if a[0] == b[0] and max(a[1], b[1]) - min(a[1] + a[3], b[1] + b[3]) < gap and max(a[2], b[2]) - min(a[2] + a[4], b[2] + b[4]) < gap: par[fd(i)] = fd(j)
    return len({fd(i) for i in range(len(V))})
NGF = fac_groups(FV)
STR = {st: sum(r['ns'] for r in rows if r['st'] == st and r['z'] in ('fac', 'lan', 'wh', 'roof')) for st in (1, 2)}   # склад-північ і АБК — окремими групами
