it(1, 'Кріплення · фасади', 'Кронштейн L60×60×5 з пазом + анкер M10 (оцінка ціни)', 'компл', VM['anchors'], 1.60, h=0.25)
it(1, 'Кріплення · фасади', 'Притиск крайній Al 80 мм з болтом', 'шт', 4 * NV, 0.45)
it(1, 'Кріплення · фасади', 'Трос безпеки модуля з карабіном (оцінка ціни)', 'шт', NV + NC, 1.00, h=0.05)
it(1, 'Кріплення · фасади', 'Козирок 25°: консолі, підкоси, пластини, анкери M12 (≈0,55 т сталі, оцінка)', 'модуль', NC, 33.0, h=1.5)
it(1, 'Кріплення · ліхтарі', 'Рейка 41×41 на каркасі ліхтаря (на склі), +5 %', 'м', round(845.548 * 1.05), 1.35, h=0.05)
it(1, 'Кріплення · ліхтарі', 'Притиск середній / кінцевий Al', 'шт', round(652 * 1.03), 0.50)
it(1, 'Кріплення · ліхтарі', 'Кронштейн рейки до каркаса (кутник з болтами, оцінка ціни)', 'шт', round(868 * 1.03), 2.00, h=0.15)
it(1, 'Кріплення · склад', 'Міні-рейки, притиски, метизи на профнастилі (за КП 26.10, на модуль)', 'модуль', 176, 21500 / 1925)
it(1, 'Монтаж модулів', 'Фасад: модуль з автовишки (оцінка 1,2 люд.год)', 'шт', NV + NC, 0, 'ua', h=1.2)
it(1, 'Монтаж модулів', 'Ліхтар на склі: модуль з рейками (оцінка 0,8 люд.год)', 'шт', 316, 0, 'ua', h=0.8)
it(1, 'Монтаж модулів', 'Склад: модуль на скаті', 'шт', 176, 0, 'ua', h=0.40)
# ---------- етап 2: кріплення варіанта Б на В1 — питомо на модуль з кошторису Б (1 749 модулів)
k = 1831 / 1749
for nm, u, q, p, h in (('Лага 41×41×1,5 перфорована оцинкована (4 800 / 2 400)', 'м', 5282.7, 1.56, 0.0485), ('Гільза 200 з муфтою M10×50', 'шт', 1989.8, 0.90, 0.0571),
                       ('Болт M10×60 + 2 шайби + гайка + трубка', 'компл', 3979.5, 0.12, 0), ('Шпилька M10 права/ліва', 'м', 2202.1, 0.59, 0), ('Встановлення шпильки з контргайками', 'шт', 1631, 0, 0.06),
                       ('Гайки M10 праві + ліві', 'шт', 3425.1 + 1712.6, 0.017, 0), ('Профіль 41×41×1,5 крайній і через прохід', 'м', 579.3, 1.56, 0), ('Кутник 160/150 t = 8', 'шт', 935.2, 0.98, 0),
                       ('Болт M10×70 / M10×60 + гайка (кутники)', 'компл', 3091.2, 0.10, 0), ('Встановлення крайнього профілю з 2 кутниками', 'шт', 454, 0, 0.35),
                       ('Притиск середній / Z33 з болтом', 'шт', 7622, 0.45, 0), ('Болт M8×20 + шайба DIN 9021 (лага → блок)', 'компл', 5884.2, 0.05, 0)):
    it(2, 'Кріплення · дах В1', nm, u, round(q * k, 1), p, 'cn' if p else 'ua', h=h)
