    it(st, 'Кабелі DC 1×6', "Роз'єм MC4, пара (3,6 на стрінг)", 'пар', round(STR[st] * 3.6), 0.44, h=0.19)
    it(st, 'Кабелі DC 1×6', 'Металорукав Ø25 у ПВХ, втулки, стяжки, бирки', 'стрінг', STR[st], 3.39 * 0.58 + 1.9 * 0.03 + 0.4 + 5.8 * 0.05, h=0.2)
