YS_, Y1_, Y2_, YN_ = -0.17, 31.34, 62.70, 96.26
box_blk = {st: len([r for r in nl[st] if r['z'] == 'roof' and abs(r['Y'] - Y1_) + 0 < 1e-6 or (r['z'] == 'roof' and r['st'] == st and abs(r['Y'] - Y2_) < 1e-6)]) for st in (1, 2)}
box_blk = {st: len([r for r in nl[st] if r['z'] == 'roof' and (abs(r['Y'] - Y1_) < 1e-6 or abs(r['Y'] - Y2_) < 1e-6)]) for st in (1, 2)}
box_par = {st: len([r for r in nl[st] if (r['z'] == 'roof' or r.get('roof')) and (abs(r['Y'] - YS_) < 1e-6 or abs(r['Y'] - YN_) < 1e-6)]) for st in (1, 2)}
nfac5 = len([r for r in nl[1] if r['z'] == 'fac' and r.get('roof') and r['f'] != 'S'])
it(1, 'Баласт · лотки і щити', 'Блок з муфтою і матом — опори лотків на блоках (0,77 на 1 м), рами щитів ліхтарів (4 × 4)' + (f' і щитів фасаду на даху ({4 * nfac5})' if nfac5 else ''), 'шт', round(roof_blk[1] * 0.77 + 16 + 4 * nfac5), 3.00, 'ua', h=0.0396)
it(2, 'Баласт · лотки і щити', 'Блок з муфтою і матом — опори лотків на блоках (0,77 на 1 м) і рами щитів у проходах Сх–Зх (4 на щит, рама над лотком)', 'шт', round(roof_blk[2] * 0.77 + 4 * box_blk[2]), 3.00, 'ua', h=0.0396)
n1N = len([r for r in rows if r['K'] in ('K-4', 'K-5') and r['st'] == 1])
for st in (1, 2):
    q = roof_par[st] + MNT[st].get('fac', 0.0) + (28.0 if (n1N > 0) == (st == 1) else 0.0) + 2 * box_par[st]
    it(st, 'Лотки і траси', 'Кронштейни лотка з анкерами через 1,0 м: на парапеті (смуги Пд, Пн, схід), на фасаді, на стіні над ТП-6923; по 2 на щит біля парапету', 'шт', round(q), 3.09, h=0.38)
    nc = len([c for c in CROSS if c[3] == st]) + NBX[st]
    if nc: it(st, 'Лотки і траси', 'Перехідний місток через лоток на ходовій смузі / в проході (рифлена сталь 1,2 м), разом із переходом стрінгів біля щитів', 'шт', nc, 35.0, 'ua', h=0.5, note='оцінка ціни')
it(1 if n1N else 2, 'Лотки і траси', 'Місток над приямком ТП-6923 на берму, стійки на бермі', 'компл', 1, 250.0, 'ua', h=12.0, note='оцінка')
# ---------- блискавкозахист і вирівнювання
