    it(st, 'Блискавкозахист', 'ПЗІП DC тип 2 (F2) на вході ШВ, на лінію', 'шт', len([r for r in nl[st] if r['z'] not in ('wh', 'abk', 'whn')]), 30.73, h=0.5)
