it(1, 'Блискавкозахист', 'ПЗІП DC тип 1+2 (F3) — лінії складу і АБК (з інших будівель)', 'шт', len([r for r in nl[1] if r['z'] in ('wh', 'abk', 'whn')]), 47.68, h=0.5)
