# ---------------- підсумки
def tot(st):
    c = collections.Counter(); h = collections.Counter()
    for x in items[st]: c[x['grp']] += x['cost']; h[x['grp']] += x['h']
    return c, h
# маса металу (оцінка): лага 1,45 кг/м, рейка 2,5 — 2,1 кг/м, профіль ліхтаря 1,45, гільза 0,45, шпилька 0,48 кг/м, кутник 1,2, притиск 0,1 (Al), блок 13 кг
mass = {1: dict(steel=VM['rail_m'] * 2.1 + VM['anchors'] * 0.45 + 550 + 845.5 * 1.05 * 1.45 + 868 * 0.35 + 176 * 3.0, al=(4 * NV + 652) * 0.1, ballast=(roof_tray[1] * 0.77 + 16) * 13),
        2: dict(steel=k * (5282.7 * 1.45 + 1989.8 * 0.45 + 2202.1 * 0.48 + 579.3 * 1.45 + 935.2 * 1.2 + (3979.5 + 3091.2) * 0.06 + 5884.2 * 0.02), al=k * 7622 * 0.1, ballast=(k * (4803.6 + 856.5) + roof_tray[2] * 0.77 + 4 * nbox[2]) * 13)}
# трей-сталь
for st in (1, 2):
    tk = {'100×50': 2.2, '200×50': 3.3, '300×100': 5.6, '400×100': 7.0, '600×100': 9.8}
    mass[st]['steel'] += sum(L * tk[w] for w, L in T[st].items()) * 1.3
# ---------------- втрати
STRLOSS = {st: sum(1 for _ in range(STR[st])) * (17.51 ** 2 * 0.0196 * 46.6 / 6 / 1000) * (TAU * (0.75 if st == 1 else 1.0)) for st in (1, 2)}
LINELOSS = {st: sum(r['e'] for r in nl[st]) for st in (1, 2)}
GEN = {st: sum(r.get('kwh', 0) for r in nl[st] if r['z'] in ('fac', 'lan', 'roof')) / 1000 + (148.7 if st == 1 else 0) for st in (1, 2)}   # МВт·год для % втрат: фасади, ліхтарі, дах — зі щитів; склад-південь — 148,7 (двійник)
if __name__ == '__main__':
    for st in (1, 2):
        c, h = tot(st); print(f'\n=== ЕТАП {st}: BOS ${sum(c.values()):,.0f}, люд.год {sum(h.values()):,.0f} (≈${sum(h.values()) * RATE:,.0f})')
        for g in c: print(f'  {g:28s} {c[g]:9,.0f} $  {h[g]:7,.0f} год')
        print('  маса, т:', {k_: round(v / 1000, 1) for k_, v in mass[st].items()})
        print(f'  втрати: стрінги {STRLOSS[st]/1000:.1f} МВт·год, лінії {LINELOSS[st]/1000:.1f} МВт·год → {(STRLOSS[st]+LINELOSS[st])/1000/GEN[st]*100:.2f} % від {GEN[st]:.0f}')
    json.dump({'items': items, 'mass': mass, 'STRLOSS': STRLOSS, 'LINELOSS': LINELOSS, 'roof_tray': roof_tray, 'nbox': nbox, 'STR': STR, 'whn': ({k: WN[k] for k in ('n', 'ns', 'kwp', 'y', 'mwh', 'free')} if WN else None)}, open('bom.json', 'w'), ensure_ascii=False)
